impl DiagnosticSample {
    fn capture(inner: &ServerState) -> Self {
        Self {
            mux: inner.engine.state.snapshot(),
            terminals: inner
                .terminals
                .iter()
                .map(|(pane, terminal)| (*pane, Arc::clone(terminal)))
                .collect(),
            command_outputs: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.command_output.as_ref().map(|value| (id, value)))
                .map(|(client, output)| (*client, output.pane, Arc::clone(&output.terminal)))
                .collect(),
            subscribers: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.subscriber.as_ref().map(|value| (id, value)))
                .map(|(client, subscriber)| (*client, Arc::clone(subscriber)))
                .collect(),
            attached: inner.attached.clone(),
            visible_terminals: inner
                .clients
                .iter()
                .filter_map(|(id, client)| {
                    client
                        .visible_terminals
                        .as_ref()
                        .map(|value| (*id, value.clone()))
                })
                .collect(),
            key_clients: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.key_engine.as_ref().map(|_| id))
                .copied()
                .collect(),
            copy_sessions: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.copy_session.as_ref().map(|value| (*id, *value)))
                .collect(),
            swallowed_keys: inner
                .clients
                .iter()
                .filter_map(|(id, client)| {
                    client
                        .swallowed_keys
                        .as_ref()
                        .map(|value| (*id, value.clone()))
                })
                .collect(),
            suppressed_text: inner
                .clients
                .iter()
                .filter_map(|(id, client)| {
                    client
                        .suppressed_text
                        .as_ref()
                        .map(|value| (*id, value.clone()))
                })
                .collect(),
            pending_committed_text: inner
                .clients
                .iter()
                .filter_map(|(id, client)| {
                    client
                        .pending_committed_text
                        .as_ref()
                        .map(|value| (*id, value.clone()))
                })
                .collect(),
            command_prompts: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.command_prompt.as_ref().map(|_| id))
                .copied()
                .collect(),
            choose_trees: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.choose_tree.as_ref().map(|_| id))
                .copied()
                .collect(),
            choose_buffers: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.choose_buffer.as_ref().map(|_| id))
                .copied()
                .collect(),
            display_panes: inner
                .clients
                .iter()
                .filter_map(|(id, client)| client.display_panes.as_ref().map(|_| id))
                .copied()
                .collect(),
            command_history: inner.history.command_history.clone(),
            paste_buffers: inner.buffers.paste_buffers.clone(),
            active_copy_pipes: inner.jobs.active_copy_pipes,
        }
    }
}

#[derive(Debug)]
struct PendingGuiRequest {
    client: ClientId,
    reply: cmdq::Reply<Result<String, String>>,
    screenshot: Option<PendingScreenshot>,
}

#[derive(Debug)]
struct PendingScreenshot {
    path: String,
    png: Vec<u8>,
}

fn owned_gui_request(
    inner: &mut ServerState,
    client: ClientId,
    request_id: u64,
) -> Option<&mut PendingGuiRequest> {
    let pending = inner.transfers.pending_gui_requests.get_mut(&request_id)?;
    if pending.client != client {
        log::warn!(target: "zz_daemon::diagnostics::connection", "discarding GUI response for request={request_id} from client={client}; owner is {}", pending.client);
        return None;
    }
    Some(pending)
}

impl ServerState {
    fn border_cycling(&self) -> bool {
        let mut cycling = self.border_cycle.lock();
        cycling.retain(|client| self.clients.contains_key(client));
        !cycling.is_empty()
    }

    #[inline]
    fn client(&self, id: ClientId) -> Option<&Client> {
        self.clients.get(&id).map(Box::as_ref)
    }

    #[inline]
    fn client_mut(&mut self, id: ClientId) -> Option<&mut Client> {
        self.clients.get_mut(&id).map(Box::as_mut)
    }

    #[inline]
    fn client_entry(&mut self, id: ClientId) -> &mut Client {
        self.clients.entry(id).or_default()
    }

    fn terminals_mut(&mut self) -> &mut BTreeMap<PaneId, Arc<TerminalSession>> {
        Arc::make_mut(&mut self.terminals)
    }
}

