fn note_snapshot_sent(inner: &mut ServerState, client: ClientId, snapshot: &MuxSnapshot) {
    inner
        .client_entry(client)
        .published_snapshot
        .replace((snapshot.content_digest(), snapshot.generation));
}

fn simulator_panes(inner: &ServerState) -> BTreeMap<PaneId, SimulatorDescriptor> {
    inner
        .engine
        .state
        .windows
        .values()
        .flat_map(|window| window.panes.values())
        .filter_map(|pane| match &pane.kind {
            PaneKind::Simulator(descriptor) => Some((pane.id, descriptor.clone())),
            _ => None,
        })
        .collect()
}

#[cfg(feature = "agent")]
fn record_agent_parents(
    inner: &mut ServerState,
    client: ClientId,
    context: &ExecutionContext,
    command_name: &str,
    effects: &[MuxEffect],
) -> Vec<PaneId> {
    let caller = inner
        .client(context.replay_client().unwrap_or(client))
        .and_then(|client| client.origin)
        .filter(|origin| is_agent_chat(inner, *origin));
    let opens = matches!(command_name, "new-pane" | "split-window" | "new-window");
    let mut first_chat = true;
    let mut children = Vec::new();
    for effect in effects {
        let MuxEffect::PaneCreated { pane, kind, .. } = effect else {
            continue;
        };
        let opened = matches!(kind, PaneKindSnapshot::Agent(_)) && std::mem::take(&mut first_chat);
        let reopened = context.agent_parent().filter(|_| opened);
        let parent = reopened.or_else(|| {
            caller.filter(|caller| {
                caller != pane
                    && ((opened && opens) || inner.engine.agent_parent(*caller).is_some())
            })
        });
        if let Some(parent) = parent {
            inner.engine.set_agent_parent(*pane, parent);
            children.push(*pane);
        }
    }
    publish_agent_parents(inner);
    children
}

fn publish_agent_parents(inner: &mut ServerState) {
    if *inner.engine.agent_parents() == inner.published_agent_parents {
        return;
    }
    inner.published_agent_parents = inner.engine.agent_parents().clone();
    let message = Shared::event(EventPayload::AgentParents {
        parents: inner.published_agent_parents.clone(),
    });
    let Ok(encoded) = zz_protocol::encode_protocol_message(&message).map(Arc::<[u8]>::from) else {
        return;
    };
    for subscriber in inner
        .clients
        .values()
        .filter_map(|client| client.subscriber.as_ref())
    {
        let _ = subscriber.enqueue_reliable_frame(&message, Arc::clone(&encoded).into(), true);
    }
}

fn send_agent_parents(inner: &ServerState, outbound: &OutboundMailbox) {
    let parents = inner.engine.agent_parents();
    if !parents.is_empty() {
        Shared::send_event(
            outbound,
            EventPayload::AgentParents {
                parents: parents.clone(),
            },
        );
    }
}

fn changed_simulator_panes(inner: &mut ServerState) -> Vec<(PaneId, SimulatorDescriptor)> {
    let current = simulator_panes(inner);
    let changed = current
        .iter()
        .filter(|(pane, descriptor)| {
            inner.artifact_state.published_simulators.get(pane) != Some(descriptor)
        })
        .map(|(pane, descriptor)| (*pane, descriptor.clone()))
        .collect();
    inner.artifact_state.published_simulators = current;
    changed
}

fn stamped_snapshot_sends(
    inner: &mut ServerState,
    tracked: bool,
    snapshot: &MuxSnapshot,
    facts: &FormatHookFacts,
) -> Vec<(Arc<OutboundMailbox>, MuxSnapshot)> {
    let presence = snapshot_presence(inner);
    let mut sends = Vec::with_capacity(
        inner
            .clients
            .values()
            .filter(|c| c.subscriber.is_some())
            .count(),
    );
    let mut unchanged = Vec::new();
    let mut restamp = false;
    for (client, subscriber) in inner.clients.iter().filter_map(|(id, client)| {
        client
            .subscriber
            .as_ref()
            .map(|subscriber| (id, subscriber))
    }) {
        if inner
            .client(*client)
            .is_some_and(|c| c.ctrl_subscriptions.is_some())
        {
            continue;
        }
        let mut client_snapshot = snapshot.clone();
        stamp_snapshot_for_client_with(inner, *client, &mut client_snapshot, &presence, facts);
        let digest = client_snapshot.content_digest();
        let sent = inner
            .client(*client)
            .and_then(|c| c.published_snapshot.as_ref())
            .copied();
        if sent == Some((digest, snapshot.generation)) {
            unchanged.push(*client);
            continue;
        }
        restamp |= sent.is_some_and(|(sent_digest, sent_generation)| {
            sent_digest != digest && sent_generation == snapshot.generation
        });
        sends.push((*client, Arc::clone(subscriber), client_snapshot, digest));
    }
    let generation = if restamp {
        inner.engine.state.bump_generation();
        let generation = inner.engine.state.generation();
        if tracked {
            inner.publication.last_published_mux_generation = generation;
        }
        for client in unchanged {
            if let Some((_, sent_generation)) = inner
                .client_mut(client)
                .and_then(|c| c.published_snapshot.as_mut())
            {
                *sent_generation = generation;
            }
        }
        generation
    } else {
        snapshot.generation
    };
    sends
        .into_iter()
        .map(|(client, subscriber, mut client_snapshot, digest)| {
            client_snapshot.generation = generation;
            inner
                .client_entry(client)
                .published_snapshot
                .replace((digest, generation));
            (subscriber, client_snapshot)
        })
        .collect()
}

fn stamp_snapshot_for_client(
    inner: &ServerState,
    client: ClientId,
    snapshot: &mut MuxSnapshot,
    presence: &SnapshotPresence,
) {
    let facts = format_hook_facts(inner);
    stamp_snapshot_for_client_with(inner, client, snapshot, presence, &facts);
}

fn stamp_snapshot_for_client_with(
    inner: &ServerState,
    client: ClientId,
    snapshot: &mut MuxSnapshot,
    presence: &SnapshotPresence,
    facts: &FormatHookFacts,
) {
    snapshot.focused_window = client_focused_window_for_attachment(inner, client);
    for session in &mut snapshot.sessions {
        session.viewers = presence
            .get(&session.id)
            .into_iter()
            .flatten()
            .map(|(viewer_client, viewer)| SessionViewer {
                is_self: *viewer_client == client,
                ..viewer.clone()
            })
            .collect();
    }
    let format_client = client_attached_session(inner, client)
        .map_or(FormatClient::Unattached, FormatClient::Attached);
    let contexts = inner.engine.format_context_snapshot(format_client);
    expand_window_status_labels(
        &inner.engine,
        &inner.config.config_files,
        facts,
        &contexts,
        snapshot,
    );
    stamp_pane_border_colours(
        &inner.engine,
        &inner.config.config_files,
        facts,
        &contexts,
        snapshot,
    );
    let border_cycle = stamp_pane_border_chrome(
        &inner.engine,
        &inner.config.config_files,
        facts,
        &contexts,
        snapshot,
    );
    let mut cycling = inner.border_cycle.lock();
    if border_cycle {
        cycling.insert(client);
    } else {
        cycling.remove(&client);
    }
    drop(cycling);
    drop(contexts);
    stamp_pane_modes(inner, facts, snapshot);
}

fn stamp_pane_modes(inner: &ServerState, facts: &FormatHookFacts, snapshot: &mut MuxSnapshot) {
    if inner.modes.pane_modes.is_empty() {
        return;
    }
    let engine = &inner.engine;
    for session in &mut snapshot.sessions {
        for window in &mut session.windows {
            for (pane, pane_snapshot) in &mut window.panes {
                pane_snapshot.mode = inner
                    .modes
                    .pane_modes
                    .get(pane)
                    .and_then(|modes| modes.last())
                    .map(|mode| match mode {
                        PaneModeRequest::Clock => {
                            let (colour, style) = engine.clock_mode_options(window.id);
                            PaneMode::Clock {
                                time: clock_mode_time(facts, style),
                                colour,
                            }
                        }
                        PaneModeRequest::Customize(mode) => {
                            let mut expand = customize_expander(inner, *pane, facts);
                            let (state, mut presentation, prompt) =
                                engine.customize_presentation(*pane, mode, &mut expand);
                            presentation.selection_style =
                                chooser_presentation::tree_selection_style_for_pane(inner, *pane);
                            presentation.border_style =
                                chooser_presentation::border_style_for_pane(inner, *pane);
                            let (prompt_type, prompt_flags) = mode.prompt_kind();
                            (presentation.prompt_style, presentation.prompt_cursor) =
                                chooser_presentation::mode_prompt_look(
                                    inner,
                                    chooser_presentation::pane_session(inner, *pane),
                                    prompt_type,
                                    prompt_flags,
                                    &mode.prompt_input(),
                                    mode.prompt_command_mode(),
                                );
                            let (prompt, prompt_cursor, prompt_top) = prompt.unwrap_or_default();
                            PaneMode::Customize {
                                state,
                                presentation: Box::new(presentation),
                                offset: MuxEngine::customize_offset(mode),
                                prompt,
                                prompt_cursor,
                                prompt_top,
                            }
                        }
                        PaneModeRequest::Panes(mode) => {
                            panes_mode_snapshot(inner, facts, *pane, mode)
                        }
                        PaneModeRequest::Switch(mode) => {
                            let entries = chooser_presentation::switch_matches(inner, *pane, mode);
                            let (columns, rows) = engine.pane_geometry(*pane).unwrap_or((80, 24));
                            let visible = usize::from(rows).saturating_sub(1);
                            let mut current = mode.current;
                            let mut offset = mode.offset;
                            if entries.is_empty() {
                                current = 0;
                                offset = 0;
                            } else {
                                current = current.min(entries.len() - 1);
                                if current < offset {
                                    offset = current;
                                } else if visible != 0 && current >= offset + visible {
                                    offset = current + 1 - visible;
                                }
                            }
                            let (prompt, prompt_cursor) = mode.prompt.draw(columns);
                            let (prompt_style, prompt_shape) =
                                chooser_presentation::mode_prompt_look(
                                    inner,
                                    chooser_presentation::pane_session(inner, *pane),
                                    "search",
                                    &["INCREMENTAL", "NOFORMAT"],
                                    &mode.prompt.input(),
                                    mode.prompt.command_mode(),
                                );
                            let matches = entries
                                .iter()
                                .map(|entry| {
                                    entry
                                        .columns
                                        .iter()
                                        .filter_map(|column| u16::try_from(*column).ok())
                                        .collect()
                                })
                                .collect();
                            PaneMode::Switch {
                                rows: entries.into_iter().map(|entry| entry.text).collect(),
                                selected: u32::try_from(current).unwrap_or(u32::MAX),
                                offset: u32::try_from(offset).unwrap_or(u32::MAX),
                                selection_style: chooser_presentation::mode_style_for_pane(
                                    inner, *pane,
                                ),
                                prompt,
                                prompt_style,
                                prompt_cursor,
                                matches,
                                match_style: chooser_presentation::switch_match_style(inner, *pane),
                                prompt_shape,
                            }
                        }
                    });
            }
        }
    }
}

fn panes_mode_snapshot(
    inner: &ServerState,
    facts: &FormatHookFacts,
    pane: PaneId,
    mode: &PanesMode,
) -> PaneMode {
    let engine = &inner.engine;
    let (columns, rows) = engine.pane_geometry(pane).unwrap_or((80, 24));
    let options = engine.display_panes_options(
        engine
            .state
            .window_for_pane(pane)
            .unwrap_or(mode.source_window),
    );
    let geometry = engine
        .panes_mode_geometry(mode.source_window, columns, rows)
        .unwrap_or_default();
    let active = engine
        .state
        .windows
        .get(&mode.source_window)
        .map(|window| window.active_pane);
    let captured = inner.modes.panes_mode_frames.get(&pane);
    let resized = captured.is_none_or(|captured| {
        if captured.size != Some((columns, rows)) {
            captured.resized.set(true);
        }
        captured.resized.get()
    });
    let live = if resized {
        panes_mode_live_frames(inner, mode.source_window)
    } else {
        BTreeMap::new()
    };
    let preview = captured
        .filter(|_| inner.modes.pane_mode_zooms.contains(&pane))
        .and_then(|captured| captured.frames.get(&pane));
    let frame = |area: &zz_mux::PanesModeAreaGeometry| {
        if !resized {
            return captured.and_then(|captured| captured.frames.get(&area.pane));
        }
        if area.pane == pane
            && let Some(preview) = preview
                .filter(|preview| area.width <= preview.columns && area.height <= preview.rows)
        {
            return Some(preview);
        }
        live.get(&area.pane)
    };
    let expand_in = |format: &str, session: SessionId, window: WindowId, shown: PaneId| {
        let mut context = engine.format_status_context_for_client(
            Some(session),
            Some(window),
            Some(shown),
            session,
        );
        context.set_format_value("config_files", &inner.config.config_files);
        let mut hooks = DaemonFormatHooks::command(facts).with_option_engine(engine);
        expand_format_values(format, &context, &mut hooks)
    };
    let expand = |format: &str, shown: PaneId| {
        expand_in(format, mode.source_session, mode.source_window, shown)
    };
    let border_style = engine
        .state
        .window_for_pane(pane)
        .and_then(|window| engine.state.windows.get(&window))
        .map_or_else(
            || options.border_style.clone(),
            |window| {
                let current = engine
                    .state
                    .sessions
                    .get(&window.session)
                    .map_or(window.id, |session| session.active_window);
                expand_in(&options.border_style, window.session, current, pane)
            },
        );
    let areas = geometry
        .areas
        .into_iter()
        .map(|area| {
            let colour = if Some(area.pane) == active {
                &options.active_colour
            } else {
                &options.colour
            };
            PanesModeArea {
                pane: area.pane,
                number: area.number,
                x: area.x,
                y: area.y,
                width: area.width,
                height: area.height,
                colour: expand(colour, area.pane),
                label: if options.format.is_empty() {
                    String::new()
                } else {
                    truncate_pane_indicator_label(expand(&options.format, area.pane))
                },
                viewport: frame(&area).map(|viewport| (**viewport).clone()),
            }
        })
        .collect();
    PaneMode::Panes {
        areas,
        borders: geometry
            .borders
            .into_iter()
            .map(|(x, y, cell)| PanesModeBorder { x, y, cell })
            .collect(),
        border_style,
        copy: geometry.copy,
        format: !options.format.is_empty(),
        clears: geometry.clears,
    }
}

fn customize_expander<'a>(
    inner: &'a ServerState,
    pane: PaneId,
    facts: &'a dyn crate::status::FormatFactSource,
) -> impl FnMut(&str, &BTreeMap<String, String>) -> String + 'a {
    let engine = &inner.engine;
    let window = engine.state.window_for_pane(pane);
    let session = window
        .and_then(|window| engine.state.windows.get(&window))
        .map(|window| window.session);
    let context = ExecutionContext::new(session, window, Some(pane));
    move |format, variables| {
        let mut hooks =
            DaemonFormatHooks::command_with_variables(facts, variables).with_option_engine(engine);
        engine.expand_pane_format(format, &context, None, FormatClient::NoClient, &mut hooks)
    }
}

fn clock_mode_time(facts: &dyn crate::status::FormatFactSource, style: u8) -> String {
    let mut hooks = DaemonFormatHooks::command(facts);
    let mut time = hooks.strftime(match style {
        0 => "%l:%M ",
        2 => "%l:%M:%S ",
        3 => "%H:%M:%S",
        _ => "%H:%M",
    });
    if style == 0 || style == 2 {
        let hour = hooks.strftime("%H").parse::<u32>().unwrap_or_default();
        time.push_str(if hour >= 12 { "PM" } else { "AM" });
    }
    time
}

fn stamp_pane_border_chrome(
    engine: &MuxEngine,
    config_files: &str,
    facts: &FormatHookFacts,
    contexts: &zz_mux::FormatContextSnapshot<'_>,
    snapshot: &mut MuxSnapshot,
) -> bool {
    let mut animated = false;
    for session in &mut snapshot.sessions {
        for window in &mut session.windows {
            window.pane_border_status = engine.displayed_pane_border_status(window.id);
            window.pane_border_lines = engine.pane_border_lines(window.id);
            window.pane_border_indicators = engine.pane_border_indicators(window.id);
            for float in &mut window.floating {
                float.border_lines = engine.pane_lines(float.pane);
                float.border_status = engine.floating_pane_border_status(float.pane);
            }
            let tiled_status = window.pane_border_status.is_on();
            let float_status: Vec<PaneId> = window
                .floating
                .iter()
                .filter(|float| float.border_status.is_on())
                .map(|float| float.pane)
                .collect();
            if !tiled_status && float_status.is_empty() {
                continue;
            }
            for (pane, pane_snapshot) in &mut window.panes {
                if !tiled_status && !float_status.contains(pane) {
                    continue;
                }
                let format = engine.pane_border_format(*pane);
                if format.is_empty() {
                    continue;
                }
                let mut context =
                    contexts.status_context(Some(session.id), Some(window.id), Some(*pane));
                context.set_format_value("config_files", config_files);
                let mut hooks = DaemonFormatHooks::command(facts)
                    .with_option_engine(engine)
                    .with_cycle();
                let (text, cycles) = crate::status::expand_cycle_frames(|| {
                    expand_status(&format, &context, &mut hooks)
                });
                pane_snapshot.border_status_text = text;
                animated |= cycles;
            }
        }
    }
    animated
}

fn stamp_pane_border_colours(
    engine: &MuxEngine,
    config_files: &str,
    facts: &FormatHookFacts,
    contexts: &zz_mux::FormatContextSnapshot<'_>,
    snapshot: &mut MuxSnapshot,
) {
    if !engine.has_pane_border_style_settings() {
        return;
    }
    let resolve = |value: Option<String>, session, window, pane| {
        let value = value?;
        let mut context = contexts.status_context(Some(session), Some(window), Some(pane));
        context.set_format_value("config_files", config_files);
        let mut hooks = DaemonFormatHooks::command(facts).with_option_engine(engine);
        let expanded = if value.contains("#{") {
            expand_format_values(&value, &context, &mut hooks)
        } else {
            value
        };
        zz_protocol::parse_style(&expanded)?.fg
    };
    for session in &mut snapshot.sessions {
        for window in &mut session.windows {
            for (pane, pane_snapshot) in &mut window.panes {
                let styles = engine.pane_border_style_values(*pane);
                pane_snapshot.border_colour = resolve(styles.border, session.id, window.id, *pane);
                pane_snapshot.active_border_colour =
                    resolve(styles.active_border, session.id, window.id, *pane);
            }
        }
    }
}

fn expand_window_status_labels(
    engine: &MuxEngine,
    config_files: &str,
    facts: &FormatHookFacts,
    contexts: &zz_mux::FormatContextSnapshot<'_>,
    snapshot: &mut MuxSnapshot,
) {
    for session in &mut snapshot.sessions {
        for window in &mut session.windows {
            let formats = engine.window_status_formats(window.id);
            let format = if window.id == session.active_window {
                &formats.current_format
            } else {
                &formats.format
            };
            let mut context = contexts.status_context(
                Some(session.id),
                Some(window.id),
                Some(window.active_pane),
            );
            context.set_format_value("config_files", config_files);
            let mut hooks = DaemonFormatHooks::command(facts).with_option_engine(engine);
            let style = expand_window_status_style(&formats, &context, &mut hooks);
            let label = expand_status(format, &context, &mut hooks);
            window.status_label =
                truncate_window_status_label(format!("#[{style}]#[push-default]{label}"));
        }
    }
}

fn expand_window_status_style(
    formats: &zz_mux::WindowStatusFormats,
    context: &zz_mux::StatusContext,
    hooks: &mut DaemonFormatHooks<'_>,
) -> String {
    let mut style = if context.variable("window_active").as_deref() == Some("1") {
        let current = expand_status(&formats.current_style, context, hooks);
        if current == "default" {
            expand_status(&formats.style, context, hooks)
        } else {
            current
        }
    } else {
        expand_status(&formats.style, context, hooks)
    };
    if context.variable("window_last_flag").as_deref() == Some("1") {
        let last = expand_status(&formats.last_style, context, hooks);
        append_window_status_style(&mut style, &last);
    }
    let mut bell_styled = false;
    if context.variable("window_bell_flag").as_deref() == Some("1") {
        let bell = expand_status(&formats.bell_style, context, hooks);
        if bell != "default" && !bell.is_empty() {
            append_window_status_style(&mut style, &bell);
            bell_styled = true;
        }
    }
    if !bell_styled
        && (context.variable("window_activity_flag").as_deref() == Some("1")
            || context.variable("window_silence_flag").as_deref() == Some("1"))
    {
        let activity = expand_status(&formats.activity_style, context, hooks);
        append_window_status_style(&mut style, &activity);
    }
    style
}

fn append_window_status_style(style: &mut String, layer: &str) {
    if layer == "default" || layer.is_empty() {
        return;
    }
    if !style.is_empty() {
        style.push(' ');
    }
    style.push_str(layer);
}

fn truncate_window_status_label(mut label: String) -> String {
    if label.len() <= MAX_WINDOW_STATUS_LABEL_BYTES {
        return label;
    }
    let boundary = (0..=MAX_WINDOW_STATUS_LABEL_BYTES)
        .rev()
        .find(|index| label.is_char_boundary(*index))
        .unwrap_or_default();
    label.truncate(boundary);
    label
}

fn truncate_pane_indicator_label(mut label: String) -> String {
    if label.len() <= MAX_PANE_INDICATOR_LABEL_BYTES {
        return label;
    }
    let boundary = (0..=MAX_PANE_INDICATOR_LABEL_BYTES)
        .rev()
        .find(|index| label.is_char_boundary(*index))
        .unwrap_or_default();
    label.truncate(boundary);
    label
}

fn prompt_key_spelling(input: &zz_terminal::KeyInput) -> String {
    if input.key == zz_terminal::KeyCode::Tab
        && input.modifiers.shift()
        && !input.modifiers.control()
        && !input.modifiers.alt()
    {
        return MENU_BACK_TAB_KEY.to_owned();
    }
    let mut name = input_key_name(input).into_string();
    if name.ends_with(' ') {
        name.pop();
        name.push_str("Space");
    }
    name
}

fn command_prompt_raw_key(
    prompt: &mut CommandPrompt,
    input: &zz_terminal::KeyInput,
) -> PromptKeyAction {
    if input.modifiers.platform() {
        return PromptKeyAction::Handled;
    }
    match prompt.mode {
        CommandPromptMode::Key => PromptKeyAction::SubmitAnswer(prompt_key_spelling(input)),
        CommandPromptMode::Numeric => match input.key {
            zz_terminal::KeyCode::Character(character)
                if character.is_ascii_digit()
                    && !input.modifiers.control()
                    && !input.modifiers.alt() =>
            {
                let mut encoded = [0_u8; 4];
                if prompt.insert(character.encode_utf8(&mut encoded)) {
                    PromptKeyAction::Updated
                } else {
                    PromptKeyAction::LimitExceeded
                }
            }
            _ => PromptKeyAction::SubmitAndPass,
        },
        _ => {
            let Some(character) = single_key_character(input) else {
                return PromptKeyAction::Handled;
            };
            let mut encoded = [0_u8; 4];
            if !prompt.insert(character.encode_utf8(&mut encoded)) {
                return PromptKeyAction::LimitExceeded;
            }
            if prompt.input.chars().count() == 1 {
                PromptKeyAction::SubmitAnswer(prompt.input.clone())
            } else {
                PromptKeyAction::Close
            }
        }
    }
}

fn single_key_character(input: &zz_terminal::KeyInput) -> Option<char> {
    match input.key {
        zz_terminal::KeyCode::Backspace => Some('\u{7f}'),
        zz_terminal::KeyCode::Escape => Some('\u{1b}'),
        zz_terminal::KeyCode::Enter => Some('\r'),
        zz_terminal::KeyCode::Tab => Some('\t'),
        zz_terminal::KeyCode::Character(character) if input.modifiers.control() => character
            .is_ascii()
            .then(|| char::from(character.to_ascii_uppercase() as u8 & 0x1f)),
        zz_terminal::KeyCode::Character(character) => Some(
            if input.modifiers.shift() && character.is_ascii_lowercase() {
                character.to_ascii_uppercase()
            } else {
                character
            },
        ),
        _ => None,
    }
}

fn prompt_space(character: Option<&char>) -> bool {
    character == Some(&' ')
}

fn prompt_in_list(separators: &str, character: Option<&char>) -> bool {
    character.is_some_and(|character| character.is_ascii() && separators.contains(*character))
}

enum PromptViKey {
    Edit(zz_terminal::KeyInput),
    Motion(PromptWordMotion),
    Append,
    Handled,
}

#[derive(Clone, Copy)]
enum PromptWordMotion {
    Forward { vi: bool, separators: bool },
    End { separators: bool },
    Backward { separators: bool },
}

impl PromptWordMotion {
    fn apply(self, prompt: &mut CommandPrompt) -> bool {
        let separators = std::mem::take(&mut prompt.word_separators);
        let changed = match self {
            Self::Forward {
                vi,
                separators: use_separators,
            } => prompt.move_word_right(vi, if use_separators { &separators } else { "" }),
            Self::End {
                separators: use_separators,
            } => prompt.move_end_word(if use_separators { &separators } else { "" }),
            Self::Backward {
                separators: use_separators,
            } => prompt.move_word_left(if use_separators { &separators } else { "" }),
        };
        prompt.word_separators = separators;
        changed
    }
}

fn prompt_key_input(
    input: &zz_terminal::KeyInput,
    key: zz_terminal::KeyCode,
    control: bool,
    alt: bool,
) -> zz_terminal::KeyInput {
    zz_terminal::KeyInput {
        action: input.action,
        key,
        modifiers: zz_terminal::Modifiers::new(false, control, alt, false),
        text: None,
        unshifted_codepoint: None,
    }
}

fn prompt_translate_key(prompt: &mut CommandPrompt, input: &zz_terminal::KeyInput) -> PromptViKey {
    use zz_terminal::KeyCode;
    let control = input.modifiers.control();
    let alt = input.modifiers.alt();
    let character = match input.key {
        KeyCode::Character(character) => Some(
            if input.modifiers.shift() && character.is_ascii_lowercase() {
                character.to_ascii_uppercase()
            } else {
                character
            },
        ),
        _ => None,
    };
    let plain = |key| prompt_key_input(input, key, false, false);
    let control_letter = |letter| prompt_key_input(input, KeyCode::Character(letter), true, false);
    if !prompt.command_mode {
        if control
            && let Some(letter) = character
            && matches!(
                letter.to_ascii_lowercase(),
                'a' | 'c' | 'e' | 'g' | 'h' | 'k' | 'n' | 'p' | 't' | 'u' | 'v' | 'w' | 'y'
            )
        {
            return PromptViKey::Edit(input.clone());
        }
        if control && character == Some('[') {
            prompt.command_mode = true;
            prompt.move_left();
            return PromptViKey::Handled;
        }
        if !control && !alt {
            match input.key {
                KeyCode::Escape => {
                    prompt.command_mode = true;
                    prompt.move_left();
                    return PromptViKey::Handled;
                }
                KeyCode::Tab
                | KeyCode::Enter
                | KeyCode::Backspace
                | KeyCode::Delete
                | KeyCode::ArrowDown
                | KeyCode::End
                | KeyCode::Home
                | KeyCode::ArrowLeft
                | KeyCode::ArrowRight
                | KeyCode::ArrowUp => return PromptViKey::Edit(input.clone()),
                _ => {}
            }
        }
        if (control || alt) && matches!(input.key, KeyCode::ArrowLeft | KeyCode::ArrowRight) {
            return PromptViKey::Edit(input.clone());
        }
        return PromptViKey::Append;
    }

    if input.key == KeyCode::Backspace {
        return PromptViKey::Edit(plain(KeyCode::ArrowLeft));
    }
    if control && character == Some('[') {
        return PromptViKey::Handled;
    }
    if input.key == KeyCode::Escape && !control && !alt {
        return PromptViKey::Handled;
    }
    if !control && !alt {
        match character {
            Some('A' | 'I' | 'C' | 's' | 'a') => prompt.command_mode = false,
            Some('S') => {
                prompt.command_mode = false;
                return PromptViKey::Edit(control_letter('u'));
            }
            Some('i') => {
                prompt.command_mode = false;
                return PromptViKey::Handled;
            }
            _ => {}
        }
    }
    if control && let Some(letter) = character {
        return match letter.to_ascii_lowercase() {
            'h' | 'c' => PromptViKey::Edit(input.clone()),
            _ => PromptViKey::Handled,
        };
    }
    if alt {
        return PromptViKey::Handled;
    }
    match input.key {
        KeyCode::Enter => return PromptViKey::Edit(plain(KeyCode::Enter)),
        KeyCode::Delete => return PromptViKey::Edit(plain(KeyCode::Delete)),
        KeyCode::ArrowDown => return PromptViKey::Edit(plain(KeyCode::ArrowDown)),
        KeyCode::ArrowLeft => return PromptViKey::Edit(plain(KeyCode::ArrowLeft)),
        KeyCode::ArrowRight => return PromptViKey::Edit(plain(KeyCode::ArrowRight)),
        KeyCode::ArrowUp => return PromptViKey::Edit(plain(KeyCode::ArrowUp)),
        _ => {}
    }
    match character {
        Some('A' | '$') => PromptViKey::Edit(plain(KeyCode::End)),
        Some('I' | '0' | '^') => PromptViKey::Edit(plain(KeyCode::Home)),
        Some('C' | 'D') => PromptViKey::Edit(control_letter('k')),
        Some('X') => PromptViKey::Edit(plain(KeyCode::Backspace)),
        Some('b') => PromptViKey::Motion(PromptWordMotion::Backward { separators: true }),
        Some('B') => PromptViKey::Motion(PromptWordMotion::Backward { separators: false }),
        Some('d') => PromptViKey::Edit(control_letter('u')),
        Some('e') => PromptViKey::Motion(PromptWordMotion::End { separators: true }),
        Some('E') => PromptViKey::Motion(PromptWordMotion::End { separators: false }),
        Some('w') => PromptViKey::Motion(PromptWordMotion::Forward {
            vi: true,
            separators: true,
        }),
        Some('W') => PromptViKey::Motion(PromptWordMotion::Forward {
            vi: true,
            separators: false,
        }),
        Some('q') => PromptViKey::Edit(control_letter('c')),
        Some('s' | 'x') => PromptViKey::Edit(plain(KeyCode::Delete)),
        Some('j') => PromptViKey::Edit(plain(KeyCode::ArrowDown)),
        Some('h') => PromptViKey::Edit(plain(KeyCode::ArrowLeft)),
        Some('a' | 'l') => PromptViKey::Edit(plain(KeyCode::ArrowRight)),
        Some('k') => PromptViKey::Edit(plain(KeyCode::ArrowUp)),
        _ => PromptViKey::Handled,
    }
}

fn command_prompt_key(
    prompt: &mut CommandPrompt,
    input: &zz_terminal::KeyInput,
    text_follows: bool,
    history: &[String],
) -> PromptKeyAction {
    if input.action == zz_terminal::KeyAction::Release {
        return PromptKeyAction::Handled;
    }
    if prompt.reads_raw_keys() {
        return command_prompt_raw_key(prompt, input);
    }
    let incremental = prompt.mode == CommandPromptMode::Incremental;
    if incremental
        && matches!(
            input.key,
            zz_terminal::KeyCode::ArrowUp
                | zz_terminal::KeyCode::ArrowDown
                | zz_terminal::KeyCode::PageUp
                | zz_terminal::KeyCode::PageDown
        )
    {
        return PromptKeyAction::Close;
    }
    let before = (prompt.command_mode, prompt.cursor);
    let translated = prompt.vi_keys.then(|| prompt_translate_key(prompt, input));
    let action = match translated {
        None => command_prompt_edit_key(prompt, input, text_follows, history),
        Some(PromptViKey::Handled) => PromptKeyAction::Handled,
        Some(PromptViKey::Motion(motion)) => {
            if motion.apply(prompt) {
                PromptKeyAction::Updated
            } else {
                PromptKeyAction::Handled
            }
        }
        Some(PromptViKey::Edit(key)) => {
            command_prompt_edit_key(prompt, &key, text_follows, history)
        }
        Some(PromptViKey::Append) => match input.key {
            zz_terminal::KeyCode::Character(character)
                if !input.modifiers.control()
                    && !input.modifiers.alt()
                    && !input.modifiers.platform() =>
            {
                if text_follows {
                    PromptKeyAction::Handled
                } else {
                    let text = input
                        .text
                        .as_deref()
                        .map_or_else(|| character.to_string(), str::to_owned);
                    if prompt.insert(&text) {
                        PromptKeyAction::Updated
                    } else {
                        PromptKeyAction::LimitExceeded
                    }
                }
            }
            _ => PromptKeyAction::Handled,
        },
    };
    match action {
        PromptKeyAction::Handled if (prompt.command_mode, prompt.cursor) != before => {
            PromptKeyAction::Updated
        }
        PromptKeyAction::Updated if incremental => PromptKeyAction::Incremental('='),
        PromptKeyAction::Submit if incremental => PromptKeyAction::SubmitIncremental,
        other => other,
    }
}

fn command_prompt_edit_key(
    prompt: &mut CommandPrompt,
    input: &zz_terminal::KeyInput,
    text_follows: bool,
    history: &[String],
) -> PromptKeyAction {
    let changed = |changed| {
        if changed {
            PromptKeyAction::Updated
        } else {
            PromptKeyAction::Handled
        }
    };
    let control = input.modifiers.control();
    let alt = input.modifiers.alt();
    let platform = input.modifiers.platform();

    let backspace = |prompt: &mut CommandPrompt| {
        if prompt.mode == CommandPromptMode::BackspaceExit && prompt.input.is_empty() {
            PromptKeyAction::Close
        } else {
            changed(prompt.delete_backward())
        }
    };

    match input.key {
        zz_terminal::KeyCode::Enter => PromptKeyAction::Submit,
        zz_terminal::KeyCode::Escape => PromptKeyAction::Close,
        zz_terminal::KeyCode::Backspace => backspace(prompt),
        zz_terminal::KeyCode::Delete => changed(prompt.delete_forward()),
        zz_terminal::KeyCode::Home => changed({
            let changed = prompt.cursor != 0;
            prompt.cursor = 0;
            changed
        }),
        zz_terminal::KeyCode::End => changed({
            let changed = prompt.cursor != prompt.input.len();
            prompt.cursor = prompt.input.len();
            changed
        }),
        zz_terminal::KeyCode::ArrowLeft if control || alt => {
            changed(PromptWordMotion::Backward { separators: true }.apply(prompt))
        }
        zz_terminal::KeyCode::ArrowRight if control || alt => changed(
            PromptWordMotion::Forward {
                vi: false,
                separators: true,
            }
            .apply(prompt),
        ),
        zz_terminal::KeyCode::ArrowLeft if platform => changed({
            let changed = prompt.cursor != 0;
            prompt.cursor = 0;
            changed
        }),
        zz_terminal::KeyCode::ArrowRight if platform => changed({
            let changed = prompt.cursor != prompt.input.len();
            prompt.cursor = prompt.input.len();
            changed
        }),
        zz_terminal::KeyCode::ArrowLeft => changed(prompt.move_left()),
        zz_terminal::KeyCode::ArrowRight => changed(prompt.move_right()),
        zz_terminal::KeyCode::ArrowUp => changed(prompt.history_up(history)),
        zz_terminal::KeyCode::ArrowDown => changed(prompt.history_down(history)),
        zz_terminal::KeyCode::Character(character) if control => {
            match character.to_ascii_lowercase() {
                'a' => changed({
                    let changed = prompt.cursor != 0;
                    prompt.cursor = 0;
                    changed
                }),
                'e' => changed({
                    let changed = prompt.cursor != prompt.input.len();
                    prompt.cursor = prompt.input.len();
                    changed
                }),
                'b' => changed(prompt.move_left()),
                'f' => changed(prompt.move_right()),
                'p' => changed(prompt.history_up(history)),
                'n' => changed(prompt.history_down(history)),
                'h' => backspace(prompt),
                'd' => changed(prompt.delete_forward()),
                'u' => changed(prompt.clear()),
                'k' => changed(prompt.delete_to_end()),
                'w' => changed({
                    let separators = std::mem::take(&mut prompt.word_separators);
                    let deleted = prompt.delete_previous_word(&separators);
                    prompt.word_separators = separators;
                    deleted
                }),
                'c' | 'g' | '[' => PromptKeyAction::Close,
                letter @ ('r' | 's') if prompt.mode == CommandPromptMode::Incremental => {
                    PromptKeyAction::Incremental(prompt.incremental_prefix(letter == 'r'))
                }
                _ => PromptKeyAction::Handled,
            }
        }
        zz_terminal::KeyCode::Character(character) if alt => match character.to_ascii_lowercase() {
            'b' => changed(PromptWordMotion::Backward { separators: true }.apply(prompt)),
            'f' => changed(
                PromptWordMotion::Forward {
                    vi: false,
                    separators: true,
                }
                .apply(prompt),
            ),
            _ => PromptKeyAction::Handled,
        },
        zz_terminal::KeyCode::Character(_) if platform => PromptKeyAction::Handled,
        zz_terminal::KeyCode::Character(character) => {
            if text_follows {
                PromptKeyAction::Handled
            } else {
                let text = input
                    .text
                    .as_deref()
                    .map_or_else(|| character.to_string(), str::to_owned);
                if prompt.insert(&text) {
                    PromptKeyAction::Updated
                } else {
                    PromptKeyAction::LimitExceeded
                }
            }
        }
        zz_terminal::KeyCode::Tab
        | zz_terminal::KeyCode::Insert
        | zz_terminal::KeyCode::PageUp
        | zz_terminal::KeyCode::PageDown
        | zz_terminal::KeyCode::Function(_)
        | zz_terminal::KeyCode::Unidentified
        | zz_terminal::KeyCode::User(_) => PromptKeyAction::Handled,
    }
}

struct ShutdownBlocker {
    shared: Arc<Shared>,
    detached: bool,
}

impl ShutdownBlocker {
    fn acquire(shared: &Arc<Shared>, detached: bool) -> Option<Self> {
        let mut blockers = shared.shutdown_blockers.lock();
        if blockers.closed {
            return None;
        }
        blockers.active = blockers
            .active
            .checked_add(1)
            .expect("shutdown blocker count overflow");
        if detached {
            blockers.detached = blockers
                .detached
                .checked_add(1)
                .expect("detached shutdown blocker count overflow");
        }
        drop(blockers);
        Some(Self {
            shared: Arc::clone(shared),
            detached,
        })
    }

    fn fork(&self, detached: bool) -> Self {
        let mut blockers = self.shared.shutdown_blockers.lock();
        blockers.active = blockers
            .active
            .checked_add(1)
            .expect("shutdown blocker count overflow");
        if detached {
            blockers.detached = blockers
                .detached
                .checked_add(1)
                .expect("detached shutdown blocker count overflow");
        }
        drop(blockers);
        Self {
            shared: Arc::clone(&self.shared),
            detached,
        }
    }
}

impl Drop for ShutdownBlocker {
    fn drop(&mut self) {
        let resume_shutdown = {
            let mut blockers = self.shared.shutdown_blockers.lock();
            blockers.active = blockers
                .active
                .checked_sub(1)
                .expect("shutdown blocker count underflow");
            if self.detached {
                blockers.detached = blockers
                    .detached
                    .checked_sub(1)
                    .expect("detached shutdown blocker count underflow");
            }
            blockers.closed && blockers.active == 0
        };
        if resume_shutdown {
            self.shared
                .request_shutdown_with_hooks(self.shared.shutdown_forced.load(Ordering::Acquire));
        }
    }
}

