struct ShellJobProcess {
    pid: u32,
    cancel: Arc<AtomicBool>,
}

#[cfg(unix)]
type ShellFinish = Box<
    dyn FnOnce(
            &Arc<Shared>,
            &mut ExecutionContext,
            Option<&CommandQueueExecution>,
            Result<ShellJobResult, ()>,
        ) -> Result<Execution, DaemonError>
        + Send,
>;

#[cfg(unix)]
struct ShellWait {
    continuation: cmdq::WaitContinuation,
    result: Arc<Mutex<Option<Result<ShellJobResult, ()>>>>,
    finish: ShellFinish,
}

#[cfg(unix)]
impl ShellWait {
    fn new(
        shared: &Arc<Shared>,
        finish: impl FnOnce(
            &Arc<Shared>,
            &mut ExecutionContext,
            Option<&CommandQueueExecution>,
            Result<ShellJobResult, ()>,
        ) -> Result<Execution, DaemonError>
        + Send
        + 'static,
    ) -> (
        Self,
        impl FnOnce(Result<ShellJobResult, ()>) + Send + 'static,
    ) {
        let continuation = cmdq::WaitContinuation::new(
            shared
                .command_item
                .as_ref()
                .and_then(|item| item.lock().wait()),
            None,
        );
        let result = Arc::new(Mutex::new(None));
        let completed = continuation.clone();
        let output = Arc::clone(&result);
        let wake = shared.timer_tx.clone();
        (
            Self {
                continuation,
                result,
                finish: Box::new(finish),
            },
            move |result| {
                *output.lock() = Some(result);
                completed.complete();
                let _ = wake.send(timers::TimerInput::HookReady);
            },
        )
    }

    fn finish(
        self,
        shared: &Arc<Shared>,
        context: &mut ExecutionContext,
        queue: Option<&CommandQueueExecution>,
    ) -> Result<Execution, DaemonError> {
        let result = self.result.lock().take().expect("completed shell job");
        (self.finish)(shared, context, queue, result)
    }
}

struct ShellJobPermit {
    shared: Arc<Shared>,
    token: u64,
    #[cfg(unix)]
    process: Arc<Mutex<Option<ShellJobProcess>>>,
    #[cfg(unix)]
    cancel: Arc<AtomicBool>,
    #[cfg(not(unix))]
    process: Arc<Mutex<Option<Child>>>,
    managed: bool,
    shutdown_blocker: Option<ShutdownBlocker>,
}

impl ShellJobPermit {
    fn acquire(
        shared: &Arc<Shared>,
        detached: bool,
        shutdown_blocking: bool,
        shutdown_blocker: Option<ShutdownBlocker>,
    ) -> Option<Self> {
        let mut shutdown_blocker = if shutdown_blocking {
            Some(match shutdown_blocker {
                Some(blocker) => blocker,
                None => ShutdownBlocker::acquire(shared, detached)?,
            })
        } else {
            None
        };
        let mut inner = shared.inner.lock();
        if shared.stopping.load(Ordering::Acquire) && !detached
            || inner.jobs.active_shell_jobs >= MAX_SHELL_JOBS
        {
            drop(inner);
            drop(shutdown_blocker.take());
            return None;
        }
        inner.jobs.next_shell_job_token = inner.jobs.next_shell_job_token.wrapping_add(1).max(1);
        let token = inner.jobs.next_shell_job_token;
        let process = Arc::new(Mutex::new(None));
        let managed = !detached || shutdown_blocking;
        inner.jobs.active_shell_jobs += 1;
        if managed {
            inner.jobs.shell_jobs.insert(token, Arc::clone(&process));
        }
        drop(inner);
        Some(Self {
            shared: Arc::clone(shared),
            token,
            process,
            #[cfg(unix)]
            cancel: Arc::new(AtomicBool::new(false)),
            managed,
            shutdown_blocker,
        })
    }
}

impl Drop for ShellJobPermit {
    fn drop(&mut self) {
        let mut inner = self.shared.inner.lock();
        if self.managed {
            inner.jobs.shell_jobs.remove(&self.token);
        }
        inner.jobs.active_shell_jobs = inner.jobs.active_shell_jobs.saturating_sub(1);
        drop(inner);
        drop(self.shutdown_blocker.take());
    }
}

struct ShellJobResult {
    output: Vec<u8>,
    status: ExitStatus,
}

#[cfg(not(unix))]
fn run_shell_job(
    command: &str,
    cwd: &Path,
    tmux: &str,
    environment: &[(RawText, Option<RawText>)],
    default_terminal: &str,
    zz_socket: &Path,
    startup_reentry: Option<&str>,
    tmux_shim: Option<&Path>,
    zz_executable: Option<&Path>,
    show_stderr: bool,
    job_process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
    detached: bool,
    started: Option<&mpsc::SyncSender<()>>,
) -> Result<ShellJobResult, ()> {
    let cwd = existing_job_working_directory(cwd);
    let mut process = shell_process(command);
    configure_shell_job_environment(
        &mut process,
        environment,
        default_terminal,
        startup_reentry.is_some(),
        tmux,
        zz_socket.as_os_str(),
        tmux_shim,
        zz_executable,
    );
    process
        .current_dir(&cwd)
        .env("PWD", cwd.as_os_str())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(if show_stderr {
            Stdio::piped()
        } else {
            Stdio::null()
        });
    if let Some(startup_reentry) = startup_reentry {
        process.env(
            zz_daemon_client::STARTUP_REENTRY_ENVIRONMENT_VARIABLE,
            startup_reentry,
        );
    }
    let mut child = process.spawn_unmasked().map_err(|_| ())?;
    drop(child.stdin.take());
    let Some(mut stdout) = child.stdout.take() else {
        let _ = terminate_copy_pipe(&mut child);
        return Err(());
    };
    let stderr = child.stderr.take();
    install_shell_job_process(job_process, stopping, child, detached)?;
    if let Some(started) = started {
        let _ = started.send(());
    }
    let stdout = thread::spawn(move || {
        let mut output = Vec::new();
        stdout.read_to_end(&mut output).map(|_| output)
    });
    let stderr = stderr.map(|mut stderr| {
        thread::spawn(move || {
            let mut output = Vec::new();
            stderr.read_to_end(&mut output).map(|_| output)
        })
    });
    let status = wait_shell_job_process(job_process, || thread::sleep(COPY_PIPE_POLL_INTERVAL));
    let mut output = stdout.join().map_err(|_| ())?.map_err(|_| ())?;
    if let Some(stderr) = stderr {
        output.extend(stderr.join().map_err(|_| ())?.map_err(|_| ())?);
    }
    let status = status?;
    Ok(ShellJobResult { output, status })
}

#[cfg(not(unix))]
fn install_shell_job_process(
    process: &Mutex<Option<Child>>,
    stopping: &AtomicBool,
    mut child: Child,
    detached: bool,
) -> Result<(), ()> {
    let mut process = process.lock();
    if stopping.load(Ordering::Acquire) && !detached {
        drop(process);
        let _ = terminate_copy_pipe(&mut child);
        return Err(());
    }
    *process = Some(child);
    Ok(())
}

#[cfg(not(unix))]
fn try_reap_shell_job_child(child: &mut Child) -> std::io::Result<Option<ExitStatus>> {
    loop {
        match child.try_wait() {
            Err(error) if error.kind() == ErrorKind::Interrupted => {}
            result => return result,
        }
    }
}

#[cfg(not(unix))]
fn reap_shell_job_process(process: &Mutex<Option<Child>>) -> Result<Option<ExitStatus>, ()> {
    let mut process = process.lock();
    let Some(child) = process.as_mut() else {
        return Err(());
    };
    match try_reap_shell_job_child(child) {
        Ok(Some(status)) => {
            process.take();
            Ok(Some(status))
        }
        Ok(None) => Ok(None),
        Err(_) => {
            let mut child = process.take().expect("shell job process was present");
            drop(process);
            let _ = terminate_copy_pipe(&mut child);
            Err(())
        }
    }
}

#[cfg(not(unix))]
fn wait_shell_job_process(
    process: &Mutex<Option<Child>>,
    mut pause: impl FnMut(),
) -> Result<ExitStatus, ()> {
    loop {
        if let Some(status) = reap_shell_job_process(process)? {
            return Ok(status);
        }
        pause();
    }
}

fn shell_job_output(command: &str, result: &ShellJobResult) -> (RawText, u8) {
    let mut output = RawText::from_bytes(result.output.clone());
    let (exit_code, message) = shell_exit(result.status).map_or_else(
        || {
            let exit_code = result
                .status
                .code()
                .and_then(|code| u8::try_from(code).ok())
                .unwrap_or(1);
            let message = (exit_code != 0).then(|| format!("'{command}' returned {exit_code}"));
            (exit_code, message)
        },
        |signal| {
            let exit_code = u8::try_from(128_i32.saturating_add(signal)).unwrap_or(u8::MAX);
            (
                exit_code,
                Some(format!("'{command}' terminated by signal {signal}")),
            )
        },
    );
    if let Some(message) = message {
        append_inserted_output(&mut output, &message);
    }
    (output, exit_code)
}

#[cfg(unix)]
fn shell_exit(status: ExitStatus) -> Option<i32> {
    use std::os::unix::process::ExitStatusExt as _;

    status.signal()
}

#[cfg(not(unix))]
fn shell_exit(_: ExitStatus) -> Option<i32> {
    None
}

struct CopyPipePermit {
    shared: Weak<Shared>,
}

impl Drop for CopyPipePermit {
    fn drop(&mut self) {
        if let Some(shared) = self.shared.upgrade() {
            let mut inner = shared.inner.lock();
            inner.jobs.active_copy_pipes = inner.jobs.active_copy_pipes.saturating_sub(1);
        }
    }
}

struct CopyPipeEnvironment {
    variables: Vec<(RawText, Option<RawText>)>,
    default_terminal: String,
    tmux: String,
    zz_socket: PathBuf,
}

#[cfg(any(test, windows))]
fn run_copy_pipe(
    command: &str,
    data: &str,
    environment: &CopyPipeEnvironment,
) -> Result<(), String> {
    run_copy_pipe_with_timeout(command, data, environment, COPY_PIPE_TIMEOUT)
}

#[cfg(windows)]
fn run_copy_pipe_with_timeout(
    command: &str,
    data: &str,
    environment: &CopyPipeEnvironment,
    timeout: Duration,
) -> Result<(), String> {
    let mut input = tempfile::tempfile()
        .map_err(|error| format!("could not stage input in a temporary file: {error}"))?;
    input
        .write_all(data.as_bytes())
        .map_err(|error| format!("could not stage input: {error}"))?;
    input
        .seek(SeekFrom::Start(0))
        .map_err(|error| format!("could not rewind staged input: {error}"))?;

    let mut process = shell_process(command);
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt as _;

        process.process_group(0);
    }
    configure_shell_job_environment(
        &mut process,
        &environment.variables,
        &environment.default_terminal,
        false,
        &environment.tmux,
        environment.zz_socket.as_os_str(),
        None,
        None,
    );
    process
        .stdin(Stdio::from(input))
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    let mut child = process
        .spawn_unmasked()
        .map_err(|error| format!("could not start process: {error}"))?;
    let started = Instant::now();
    loop {
        match child.try_wait() {
            Ok(Some(status)) if status.success() => return Ok(()),
            Ok(Some(status)) => return Err(format!("process exited unsuccessfully ({status})")),
            Ok(None) if started.elapsed() >= timeout => {
                let (kill_error, wait_error) = terminate_copy_pipe(&mut child);
                if let Some(error) = kill_error {
                    return Err(format!(
                        "process timed out after {} seconds and could not be terminated: {error}",
                        timeout.as_secs()
                    ));
                }
                if let Some(error) = wait_error {
                    return Err(format!(
                        "process timed out after {} seconds and could not be reaped: {error}",
                        timeout.as_secs()
                    ));
                }
                return Err(format!(
                    "process timed out after {} seconds",
                    timeout.as_secs()
                ));
            }
            Ok(None) => thread::sleep(COPY_PIPE_POLL_INTERVAL),
            Err(error) => {
                terminate_copy_pipe(&mut child);
                return Err(format!("could not query process status: {error}"));
            }
        }
    }
}

